export const HERITAGE_ARC_DATA={agra:{id:"agra",name:"Agra",tagline:"The Imperial Seat of Mughal Splendor",themeColor:"#f59e0b",badge:"Mughal Architecture & Artistry",description:"Nestled along the banks of the Yamuna River, Agra is world-famous as the home of the Taj Mahal. Serving as the imperial capital of the Mughal Empire under Akbar, Jahangir, and Shah Jahan, Agra stands as a testament to architectural genius, marble inlay artistry (Pietra Dura), and grand fortifications.",monuments:[{name:"Taj Mahal",desc:"UNESCO World Heritage Site and universal symbol of eternal love built by Shah Jahan in white marble."},{name:"Agra Fort",desc:"Vast 16th-century red sandstone fortress housing royal palaces like Jahangir Mahal and Khas Mahal."},{name:"Fatehpur Sikri",desc:"Akbar's short-lived imperial capital featuring the towering Buland Darwaza and Panch Mahal."},{name:"Tomb of Itmad-ud-Daulah",desc:"Known as the 'Baby Taj', this mausoleum pioneered intricate Pietra Dura marble inlay."}],cultureFood:[{category:"Cuisine",detail:"Agra Petha (traditional ash gourd sweet), Bedai & Aloo Sabzi, and Mughlai Kebabs."},{category:"Handicrafts",detail:"Marble inlay work (Parchin Kari), Zardozi embroidery, and leather craft."},{category:"Traditions",detail:"Taj Mahotsav (10-day cultural extravaganza held every February near Shilpgram)."}]},lucknow:{id:"lucknow",name:"Lucknow",tagline:"The City of Nawabs, Tehzeeb & Culinary Art",themeColor:"#ec4899",badge:"Nawabi Heritage & Literature",description:"Situated on the banks of the Gomti River, Lucknow is renowned for its refined etiquette (Tehzeeb), classical music, Urdu literature, elegant Awadhi architecture, and world-class street food.",monuments:[{name:"Bara Imambara",desc:"Architectural wonder housing the world's largest gravity-defying unsupported vaulted hall and the famous Bhulbhulaiya labyrinth."},{name:"Chota Imambara",desc:"The Palace of Lights, adorned with chandeliers, gilded domes, and intricate calligraphic artwork."},{name:"Rumi Darwaza",desc:"60-foot monumental gateway built in 1784, inspired by Turkish architecture of Constantinople."},{name:"The Residency",desc:"Historic complex preserving preserved ruins from the 1857 Indian War of Independence."}],cultureFood:[{category:"Cuisine",detail:"Melt-in-mouth Galouti & Tunday Kebabs, Awadhi Biryani, Sheermal, and Tokri Chaat."},{category:"Handicrafts",detail:"Exquisite Chikankari shadow-stitch embroidery and Kamdani tinsel work."},{category:"Traditions",detail:"Kathak dance heritage of Lucknow Gharana, Gazal soirees, and Lucknow Mahotsav."}]},varanasi:{id:"varanasi",name:"Varanasi",tagline:"The Eternal City & Spiritual Heart of India",themeColor:"#8b5cf6",badge:"Ancient Spirituality & Sacred Ganges",description:"Continuously inhabited for over 3,000 years, Varanasi (Kashi/Banaras) is the spiritual capital of India. Located on the sacred crescent bend of the River Ganges, it is a living center of philosophy, music, yoga, and ancient rituals.",monuments:[{name:"Kashi Vishwanath Temple",desc:"Sacred Jyotirlinga shrine dedicated to Lord Shiva, featuring golden spires and the modern Vishwanath Corridor."},{name:"Dashashwamedh Ghat",desc:"The oldest and most vibrant ghat, famed for its mesmerizing evening Ganga Aarti ceremony."},{name:"Sarnath",desc:"Located 10 km away, where Lord Buddha preached his first sermon after enlightenment; home to Dhamek Stupa."},{name:"Manikarnika & Harishchandra Ghats",desc:"Historic ghats central to Hindu death rituals and liberation (Moksha)."}],cultureFood:[{category:"Cuisine",detail:"Banarasi Paan, Tamatar Chaat, Malaiyyo (winter foam dessert), Kachori Sabzi, and Thandai."},{category:"Handicrafts",detail:"Lustrous Banarasi Silk Sarees woven with gold/silver Zari thread, and wooden toys."},{category:"Traditions",detail:"Evening Ganga Aarti, Benares Classical Music Gharana (Tabla & Sitar), and Dev Deepawali."}]}};export const TIMELINE_DATA=[{era:"Ancient Period (c. 1200 BCE – 6th Century BCE)",title:"Spiritual Origins in Kashi & Sarnath",description:"Varanasi emerges as a premier seat of Vedic learning. In 528 BCE, Gautama Buddha delivers his first sermon at Sarnath near Varanasi, launching the Wheel of Dhamma."},{era:"Medieval Mughal Era (1526 – 1707 CE)",title:"Architectural Zenith in Agra",description:"Emperor Akbar builds Fatehpur Sikri and expands Agra Fort. Shah Jahan constructs the magnificent Taj Mahal (1631–1653 CE), establishing Agra as a global landmark of artistic perfection."},{era:"Nawabi Era (1722 – 1856 CE)",title:"Cultural Flowering of Lucknow",description:"Nawabs of Awadh transfer their capital to Lucknow. Nawab Asaf-ud-Daula builds the Bara Imambara (1784 CE), fostering Chikankari craft, Kathak dance, and Awadhi culinary arts."},{era:"Modern Circuit (2014 – Present)",title:"Establishment of the UP Heritage Arc",description:"The Government of Uttar Pradesh formally designates the Agra-Lucknow-Varanasi circuit as the 'Heritage Arc' with expressways, Vande Bharat connectivity, and urban corridor revamps."}];export function renderCityDetails(a){const e=HERITAGE_ARC_DATA[a];if(!e)return"";const t=e.monuments.map(a=>`\n    <div class="monument-card">\n      <h4>${a.name}</h4>\n      <p>${a.desc}</p>\n    </div>\n  `).join(""),i=e.cultureFood.map(a=>`\n    <div class="highlight-box">\n      <strong>${a.category}:</strong> ${a.detail}\n    </div>\n  `).join("");return`\n    <div class="city-detail-card" id="detail-${e.id}">\n      <div class="detail-overview">\n        <span class="detail-header-badge" style="background:${e.themeColor}22; color:${e.themeColor}; border:1px solid ${e.themeColor}">\n          ${e.badge}\n        </span>\n        <h2 class="detail-title">${e.name}</h2>\n        <p class="detail-tagline">"${e.tagline}"</p>\n        <p class="detail-description">${e.description}</p>\n        <div class="cultural-highlights">\n          <h3>🎭 Cultural & Culinary Highlights</h3>\n          ${i}\n        </div>\n      </div>\n      <div class="detail-monuments">\n        <h3>🏛️ Landmark Monuments & Attractions</h3>\n        <div class="monument-grid">\n          ${t}\n        </div>\n      </div>\n    </div>\n  `}export function renderTimeline(){return TIMELINE_DATA.map((a,e)=>`\n      <div class="timeline-item ${e%2==0?"left":"right"}">\n        <div class="timeline-dot"></div>\n        <div class="timeline-content">\n          <span class="timeline-era">${a.era}</span>\n          <h3>${a.title}</h3>\n          <p>${a.description}</p>\n        </div>\n      </div>\n    `).join("")}"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("city-detail-container"),e=document.getElementById("timeline-container"),t=document.querySelectorAll(".tab-btn"),i=document.querySelectorAll(".city-node");function n(e){a&&(a.innerHTML=renderCityDetails(e)),t.forEach(a=>{const t=a.getAttribute("data-target")===e;a.classList.toggle("active",t),a.setAttribute("aria-selected",t?"true":"false")}),i.forEach(a=>{a.classList.toggle("active-node",a.getAttribute("data-city")===e)})}e&&(e.innerHTML=renderTimeline()),t.forEach(a=>{a.addEventListener("click",()=>{n(a.getAttribute("data-target"))})}),i.forEach(a=>{a.addEventListener("click",()=>{n(a.getAttribute("data-city"))}),a.addEventListener("keydown",e=>{if("Enter"===e.key||" "===e.key){e.preventDefault();n(a.getAttribute("data-city"))}})}),n("agra")});